package core

// Guidance describes implemented behavior, not parity with a commercial plugin.
type AppModuleGuidance struct {
	Description string   `json:"description"`
	Workflow    []string `json:"workflow"`
	Limitations []string `json:"limitations"`
}

func ModuleGuidance(id string) AppModuleGuidance {
	guides := map[string]AppModuleGuidance{
		"site-diagnosis":           {"检查真实网站的 DNS、HTTP、TLS、Nginx 配置及文件状态。", []string{"选择网站", "运行诊断", "按失败检查项排查"}, []string{"外部 DNS/TLS 受网络可达性影响；不会自动修改网站配置。"}},
		"network-threat-detection": {"读取真实监听端口、连接及 SSH 防暴力破解状态，对比端口基线。", []string{"确认正常端口后建立基线", "检查新增监听和公网暴露"}, []string{"端口变化检测不是流量包分析或完整 IDS；不会自动封禁新增端口。"}},
		"website-analytics":        {"独立浏览器采集与持久化统计：浏览量、访客、会话旅程、页面来源、点击坐标、标准 INP 与有界顺序转化漏斗。", []string{"选择网站；开启或关闭时自动应用网站采集代理", "将同源 JS 标签加入网站 HTML 模板", "在专用功能页查看真实采集数据，按业务页面路径计算漏斗"}, []string{"默认关闭；启停会备份、校验并重载 Nginx，失败回滚。不会自动改写 HTML。浏览器标识不等于真实人数；不包含会话录像或地理数据库。", "INP 按完整文档访问归属，不代表 SPA 路由性能；没有可测交互时不显示零分。漏斗最多 8 步、20000 条页面事件或 8 MiB 数据，截断会标记部分结果，不是支付或业务审计证据。"}},
		"website-statistics-v2":    {"统计真实请求、流量、状态码、UTC 小时趋势，并定位错误及慢请求。", []string{"选择网站和时间范围", "按路径、IP、状态码或爬虫筛选", "查看错误与慢请求明细"}, []string{"读取当前日志末尾 16 MiB，不是全量历史数据库；不包含地理位置数据库。"}},
		"files-sync":               {"增量复制内容与权限，保护目标冲突；本机受管网站支持 Linux 实时事件同步、定时补查、持久化计划与历史。", []string{"选择源和目标，先预览冲突与增量", "保存计划，可开启实时增量同步，初次开启立即补查", "核对实际监听状态，暂停、恢复或手动执行计划"}, []string{"不删除目标额外文件，不支持实时同步环；跨服务器尚未实现，隔离 PHP 项目仅手动同步。最多 32 个计划、4096 个共享目录监听，超限及失败显示降级；中断和连续失败安全暂停。"}},
		"daily-report":             {"汇总真实系统资源、网站、任务、流量、安全状态及临期证书，保存每日报告。", []string{"刷新当日报告", "检查失败任务和即将到期证书", "在面板设置的通知页启用日报 Webhook，核对实际发送记录"}, []string{"后台每日生成，每日最多生成一条推送事件；外部推送仅包含脱敏数字摘要，需接收端校验签名与去重。不内置短信或邮件运营商。"}},
		"enterprise-tamper-proof":  {"签名文件基线、持久化备份，支持 Linux 实时事件触发检查与定时补查，可选择自动恢复已备份文件。", []string{"选择网站、排除路径及自动恢复，建立可信基线", "选择策略启用实时模式，核对实际监听状态", "检查变更、暂停保护或受控恢复文件", "在面板设置通知页配置外部告警并核对发送记录"}, []string{"实时事件触发的是写入后的检查与恢复，不是内核写入拦截；新增文件不自动删除。最多 4096 个目录监听，溢出触发完整补查，超限及失败显示降级。尚无进程白名单。Webhook 只发送脱敏摘要，需接收端验签与去重。"}},
		"load-balance":             {"真实 Nginx HTTP 上游、权重、备用节点、IP 粘滞；持久事务、修订冲突与入口生效指纹。", []string{"读取入口列表并选择当前修订", "填写域名、回环端口和唯一固定 IP 节点后保存", "探测、移除入口或恢复中断事务"}, []string{"当前是 HTTP 回环入口，不含 TCP/UDP 均衡和外部告警。节点探测仅 TCP 建连，不冒充主动应用健康检查；既有请求不强制断开。"}},
		"mobile-pwa":               {"Android 原生客户端与 iOS SwiftUI 源码、未签名 arm64 设备构建；原生层负责地址、证书、后台锁屏与设备认证，业务页面连接真实面板。", []string{"打开交付下载，核对 SHA-256；Android 安装 APK，iOS 使用自己的开发者签名", "填写可达的 HTTPS 面板地址及安全入口路径，不带临时令牌", "沿用面板登录、TOTP、角色与网站范围"}, []string{"iOS 未签名构建不能直接安装或上架；正式包拒绝 HTTP 和无效证书。原生容器复用面板响应式业务 UI，无系统推送或离线管理；文件下载仍需可信浏览器登录。清除本地会话不替代服务器会话撤销；模拟器启动证明不是实机业务验收。"}},
		"apache-waf":               {"Apache 独立元数据防护：分类规则、站点策略、IP/URL/UA 名单、字面规则、观察模式和隐私事件报表。", []string{"先安装 Apache 并绑定网站", "预览并保存策略；原生校验、备份、平滑重载和指纹核对", "筛选事件、导出配置、查看升级及失败记录"}, []string{"不包含完整 POST 请求体解析、商业规则、地理封禁或 CC；服务器原生访问拒绝仍然有效。网络对端 IP 经 Nginx 代理时为回环地址，不直接信任 X-Forwarded-For。"}},
		"php-code-security":        {"扫描真实 PHP 风险代码；人工确认后原子隔离，核验私有备份并无覆盖恢复。", []string{"选择网站并扫描", "按文件、行号、规则和摘要审查", "精确确认隔离，查看隔离箱", "校验备份、修订与原位置后恢复；中断事务可显式修复"}, []string{"静态命中不等于确诊后门，不自动删除代码。", "文件隔离不是持续内核拦截；已有请求、OPcache 与其他程序重新创建路径需独立处置。", "只处理单文件不超过 8 MiB 的普通 PHP 文件；最多 512 条记录和 256 MiB 原始备份预算，保留所有备份。"}},
		"task-manager":             {"查看真实进程 CPU、内存、磁盘 I/O 与连接；通过进程身份校验终止受管进程。", []string{"刷新进程列表", "按 CPU、内存或 I/O 排序", "选择可终止的受管进程"}, []string{"只允许 SIGTERM 非 root 的云栈受管进程；不会终止系统关键进程或任意进程树。"}},
		"website-tamper-proof":     {"签名基线与 Linux 实时文件事件，检测新增、删除、内容及权限变化，支持指定文件恢复。", []string{"选择网站与排除路径，建立可信基线", "选择策略启用实时模式，核对监听状态和历史", "选择基线文件恢复或暂停监控", "在面板设置通知页配置外部告警并核对发送记录"}, []string{"事件驱动检测不是内核写入拦截；保留定时补查。最多 4096 个目录监听，扫描上限 10000 文件、单文件 8 MiB、总计 256 MiB，失败及超限会明确显示。Webhook 只发送脱敏摘要，需接收端验签与去重。"}},
		"user-manager":             {"管理真实面板用户、角色、网站范围、独立菜单授权与会话撤销；后端每次请求复核菜单上限。", []string{"刷新用户列表取得当前修订号", "选择用户或填写新用户名", "核对角色、网站范围和菜单授权后保存；旧会话立即失效"}, []string{"菜单不会扩展角色权限；操作员和只读用户不能取得全局管理菜单。至少保留一个完整权限管理员，不包含套餐或计费。"}},
		"file-monitor":             {"按排除规则建立签名基线，Linux inotify 实时触发文件和权限检查，保留定时补查、暂停恢复与可筛选的私有历史数据库。", []string{"选择网站、排除路径和补查间隔，建立可信基线", "选择策略启用实时模式，核对内核监听状态", "按网站、时间和关键词查询历史，暂停或恢复监控", "在面板设置通知页配置外部告警并核对发送记录"}, []string{"最多 4096 个目录监听，事件合并约 0.5–2 秒再检查；超限及失败显示降级，事件溢出触发完整补查。每个应用最多 100 个基线；历史保留最近 365 天、最多 100000 条摘要，不保存完整文件内容。Webhook 只发送脱敏摘要，需接收端验签与去重。"}},
		"disk-analysis":            {"统计网站目录真实文件大小、子目录分布、扩展名分布和最大文件，支持子目录扫描。", []string{"选择网站或网站内子目录", "扫描占用", "从目录分布或大文件所在目录继续下钻"}, []string{"仅扫描网站 public 目录，最多 100000 个目录/文件；分类和长路径达到报告上限时会标记部分结果，不扫描任意系统路径、不自动删除文件。"}},
		"platform-ops":             {"使用独立可撤销令牌和可信 HTTPS 聚合多个云栈主机的真实运行状态。", []string{"在被管理面板生成只读令牌", "添加 HTTPS 主机", "刷新聚合状态或撤销授权"}, []string{"当前是只读监控，不提供远程批量命令、补丁发布或任意 SSH 操作。"}},
		"nfs-manager":              {"独立 NFSv4 网站目录导出与受管远程挂载，保留配置、失败恢复及重启恢复。", []string{"旧模块先在商店更新独立运行时；不自动启动空服务", "选择网站目录、明确客户端 IP/CIDR 和只读策略", "配置本机监听并启动，通过真实 RPC 和客户端读写验收", "从列表选择共享导出或远程挂载进行管理"}, []string{"AUTH_SYS 未加密，只用于可信网络或 VPN；不提供 Kerberos 或内核硬配额。", "仅导出普通受管网站目录，全部客户端映射为网站非 root UID/GID；目录身份改变会拒绝启动。", "最多 64 个导出，每个 16 条客户端清单；最多保留 512 条 root 私有恢复记录，需安全归档。", "默认服务预算为 512 MiB、256 个任务和 2 核；不修改系统 NFS / RPC 映射、防火墙和安全组。APT 原生包经过完整摘要核对并独立解包，不执行系统 Ganesha 服务的维护脚本。"}},
		"pm2-manager":              {"真实 PM2 非 root Node 程序管理：集群、内存重启阈值、加密且仅写入的环境变量、锁定依赖后台部署、启停与日志。", []string{"准备网站 JS 入口与 package.json / package-lock.json", "创建项目，环境变量按 JSON 增量写入", "选中项目部署公共 npm 锁定依赖，查看状态；失败恢复旧依赖", "修改配置时校验修订号；中断部署可取消并恢复"}, []string{"不接受任意 API shell 命令、自定义 npm 源或本地链接。默认禁用安装脚本；显式开启后，只以网站独立用户运行第三方安装/构建代码，不传入应用环境秘密。安装限 10 分钟、768 MiB 内存，暂存目录每秒检查 512 MiB / 30000 项且保留 1 GiB 可用空间（不是磁盘内核硬配额）；新旧暂存目录保留供恢复。内存重启阈值不是内核硬限额，受管应用有 1 GiB 总硬限额。程序自身的日志可能包含秘密。"}},
		"pure-ftpd":                {"真实网站虚拟用户与 chroot，双通道强制 TLS；独立 Pure-FTPd 运行时提供账户限速、软配额、IP 访问限制、会话限制及可恢复配置和账户提交。", []string{"刷新服务；旧安装先在商店更新，不静默替换系统 FTP", "配置监听、证书及被动端口，并单独放行安全组", "选择账户设置限制；启用软配额前先停止服务并重统计，再实测 FTPS"}, []string{"IPv4，单个域名证书；不自动开放防火墙或安全组。", "容量及文件数为 FTP 软配额；同网站账户共享计数，网站程序、SSH 和其他通道可绕过，不能用于安全隔离或租户硬配额。", "默认 systemd 预算为 512 MiB、256 个任务及最多 2 个 CPU 核心；高并发登录还受密码哈希内存预算约束，不承诺任意硬件吞吐。", "限额仅作用于新连接；切换中断已有连接。证书不静默轮换，恢复备份含秘密，必须保留于 root 独占目录。"}},
	}
	return guides[id]
}
